PRAGMA foreign_keys=ON;
CREATE TABLE dim_fonte_energia(fonte_id INTEGER PRIMARY KEY,fonte TEXT UNIQUE NOT NULL,classificacao TEXT NOT NULL,fator_emissao_tco2_mwh REAL NOT NULL,custo_variavel_ref REAL NOT NULL,despachabilidade_pct REAL NOT NULL);
CREATE TABLE dim_regiao(regiao_id INTEGER PRIMARY KEY,regiao TEXT NOT NULL,uf_referencia TEXT NOT NULL,caracteristica TEXT);
CREATE TABLE dim_usina(usina_id INTEGER PRIMARY KEY,codigo TEXT UNIQUE NOT NULL,usina TEXT NOT NULL,fonte_id INTEGER NOT NULL,regiao_id INTEGER NOT NULL,capacidade_mw REAL NOT NULL,data_operacao TEXT NOT NULL,status TEXT NOT NULL,empresa TEXT NOT NULL,FOREIGN KEY(fonte_id) REFERENCES dim_fonte_energia,FOREIGN KEY(regiao_id) REFERENCES dim_regiao);
CREATE TABLE fato_geracao_mensal(geracao_id INTEGER PRIMARY KEY,usina_id INTEGER NOT NULL,competencia TEXT NOT NULL,horas_periodo INTEGER NOT NULL,geracao_bruta_mwh REAL NOT NULL,geracao_liquida_mwh REAL NOT NULL,perdas_mwh REAL NOT NULL,corte_mwh REAL NOT NULL,fator_capacidade REAL NOT NULL,disponibilidade REAL NOT NULL,indice_recurso REAL NOT NULL,FOREIGN KEY(usina_id) REFERENCES dim_usina);
CREATE TABLE fato_custo(custo_id INTEGER PRIMARY KEY,usina_id INTEGER NOT NULL,competencia TEXT NOT NULL,categoria TEXT NOT NULL,valor_rs REAL NOT NULL,FOREIGN KEY(usina_id) REFERENCES dim_usina);
CREATE TABLE fato_emissao(emissao_id INTEGER PRIMARY KEY,usina_id INTEGER NOT NULL,competencia TEXT NOT NULL,emissoes_tco2e REAL NOT NULL,intensidade_tco2_mwh REAL NOT NULL,escopo TEXT NOT NULL,FOREIGN KEY(usina_id) REFERENCES dim_usina);
CREATE TABLE fato_indisponibilidade(evento_id INTEGER PRIMARY KEY,usina_id INTEGER NOT NULL,data_inicio TEXT NOT NULL,duracao_horas REAL NOT NULL,tipo TEXT NOT NULL,causa TEXT NOT NULL,energia_nao_gerada_mwh REAL NOT NULL,FOREIGN KEY(usina_id) REFERENCES dim_usina);
CREATE TABLE dim_cliente(cliente_id INTEGER PRIMARY KEY,cliente TEXT NOT NULL,segmento TEXT NOT NULL,mercado TEXT NOT NULL);
CREATE TABLE fato_contrato(contrato_id INTEGER PRIMARY KEY,usina_id INTEGER NOT NULL,cliente_id INTEGER NOT NULL,data_inicio TEXT NOT NULL,data_fim TEXT NOT NULL,volume_mwh REAL NOT NULL,preco_rs_mwh REAL NOT NULL,receita_contratada_rs REAL NOT NULL,status TEXT NOT NULL,FOREIGN KEY(usina_id) REFERENCES dim_usina,FOREIGN KEY(cliente_id) REFERENCES dim_cliente);
CREATE TABLE fato_investimento(investimento_id INTEGER PRIMARY KEY,usina_id INTEGER NOT NULL,tipo TEXT NOT NULL,status TEXT NOT NULL,orcamento_rs REAL NOT NULL,realizado_rs REAL NOT NULL,data_inicio TEXT NOT NULL,progresso_pct INTEGER NOT NULL,FOREIGN KEY(usina_id) REFERENCES dim_usina);
CREATE INDEX idx_geracao_competencia ON fato_geracao_mensal(competencia); CREATE INDEX idx_usina_fonte ON dim_usina(fonte_id); CREATE INDEX idx_custo_usina ON fato_custo(usina_id);
